// Cria a ficha de contratado (retainer) a partir do statblock do livro.
// A lógica está em ekhoria.js — veja a função contratarDialogo().
const mod = game.modules.get("ekhoria");
if (!mod?.active) {
  ui.notifications.error("Ekhoria: o módulo não está ativo neste mundo.");
} else if (!game.ekhoria?.contratar) {
  ui.notifications.error(
    `Ekhoria ${mod.version}: o módulo está ativo, mas o script não registrou a função. `
    + "Recarregue com Ctrl+Shift+R (o navegador guarda o ekhoria.js em cache). "
    + "Se persistir, abra o console com F12 e procure por 'Ekhoria |'."
  );
} else {
  game.ekhoria.contratar();
}
